// ===== Helper functions =====

/** ดึงคำถามตาม level */
export function getQuizByLevel(level: number): SentenceQuizQuestion[] {
  return sentenceQuizQuestions.filter(q => q.level === level)
}

/** ดึงคำถามตาม type */
export function getQuizByType(type: string): SentenceQuizQuestion[] {
  return sentenceQuizQuestions.filter(q => q.type === type)
}

/** สุ่มคำถามจำนวน n ข้อ */
export function getRandomQuestions(n: number, level?: number): SentenceQuizQuestion[] {
  let pool = level ? getQuizByLevel(level) : sentenceQuizQuestions
  const shuffled = [...pool].sort(() => Math.random() - 0.5)
  return shuffled.slice(0, n)
}

/** สุ่มคำถามจากทุก type จำนวนเท่ากัน */
export function getBalancedQuiz(questionsPerType: number, level?: number): SentenceQuizQuestion[] {
  const types = ['sentence-to-meaning', 'meaning-to-sentence', 'fill-blank', 'word-in-context'] as const
  const result: SentenceQuizQuestion[] = []

  for (const type of types) {
    let pool = level
      ? sentenceQuizQuestions.filter(q => q.type === type && q.level === level)
      : sentenceQuizQuestions.filter(q => q.type === type)
    const shuffled = pool.sort(() => Math.random() - 0.5)
    result.push(...shuffled.slice(0, questionsPerType))
  }

  return result.sort(() => Math.random() - 0.5)
}

/** สถิติ Quiz */
export function getQuizStats() {
  return {
    total: sentenceQuizQuestions.length,
    byType: {
      'sentence-to-meaning': sentenceQuizQuestions.filter(q => q.type === 'sentence-to-meaning').length,
      'meaning-to-sentence': sentenceQuizQuestions.filter(q => q.type === 'meaning-to-sentence').length,
      'fill-blank': sentenceQuizQuestions.filter(q => q.type === 'fill-blank').length,
      'word-in-context': sentenceQuizQuestions.filter(q => q.type === 'word-in-context').length,
    },
    byLevel: {
      1: sentenceQuizQuestions.filter(q => q.level === 1).length,
    }
  }
}
